```

EXAMPLE - Testing insert() for NULL tree case:

Function: insert(struct node* node, int key)
Path: node == NULL → return newNode(key)

```c
#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_insert_null_tree(void) {
    // Setup: no tree exists
    struct node* root = NULL;
    int key = 42;

    // Test: insert into empty tree
    struct node* result = insert(root, key);

    // Assertions
    TEST_ASSERT_NOT_NULL(result);
    TEST_ASSERT_EQUAL_INT(42, result->key);
    TEST_ASSERT_NULL(result->left);
    TEST_ASSERT_NULL(result->right);

    // Cleanup
    free(result);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_insert_null_tree);
    return UNITY_END();
}
```

SUCCESS CRITERIA:
- Test exercises the target path with correct inputs
- All function calls exist in operation map or standard C library
- NO function implementations copied into the test (just call them)
- Memory properly managed (no leaks)
- Assertions verify expected behavior using Unity macros
- Code compiles without errors
- Test function name follows: unit_test_<function>_<scenario>

Output ONLY the C test file code. No explanations, no JSON, just compilable C code.

Generate a complete Unity C test file for the following execution path.

FUNCTION UNDER TEST:
Name: delete_bt
Signature: void delete_bt(node **root, int ele)
Description: /**
 * @brief Delete a node with a given value from a binary search tree.
 *
 * Searches for the node containing the specified element and removes it,
 * preserving the BST ordering. The tree is modified in-place. If the element
 * is not found, the function returns without making any changes.
 *
 * @param root Pointer to the root pointer of the tree. May be modified if the
 *             root node is deleted.
 * @param ele The integer value to search for and delete from the tree.
 *
 * @note Memory: The memory for the deleted node is freed.
 * @note Behavior: If the node has two children, it is replaced by its inorder
 *       successor (the smallest node in its right subtree).
 */
Dependencies: None

FUNCTION IMPLEMENTATION (REFERENCE ONLY - do NOT copy into test):
```c
// C program for the function called delete_bt
// Contains target function implementation and dependency signatures

#include <stdio.h>
#include <stdlib.h>

// Target function implementation
void delete_bt(node **root, int ele)
{
    node *temp;
    node *prev;
    if (*root == NULL)
        return;
    else
    {
        temp = *root;
        prev = NULL;
        // search
        while (temp != NULL)
        {
            if (temp->data == ele)
            {
                break;
            }
            else if (ele > temp->data)
            {
                prev = temp;
                temp = temp->rlink;
            }
            else
            {
                prev = temp;
                temp = temp->llink;
            }
        }
    }

    if (temp == NULL)
        return;
    else
    {
        node *replacement;  // deleted node's replacement
        node *t;
        if (temp->llink == NULL && temp->rlink == NULL)
        {
            replacement = NULL;
        }
        else if (temp->llink == NULL && temp->rlink != NULL)
        {
            replacement = temp->rlink;
        }
        else if (temp->llink != NULL && temp->rlink == NULL)
        {
            replacement = temp->llink;
        }
        else
        {
            replacement = temp->rlink;  // replaced with inorder successor
            t = replacement;
            while (t->llink != NULL)
            {
                t = t->llink;
            }
            t->llink =
                temp->llink;  // leftmost node of the replacement is linked to
                              // the left child of the deleted node
        }

        if (temp == *root)
        {
            free(*root);
            *root = replacement;
        }
        else if (prev->llink == temp)
        {
            free(prev->llink);
            prev->llink = replacement;
        }
        else if (prev->rlink == temp)
        {
            free(prev->rlink);
            prev->rlink = replacement;
        }
    }
}

